    int tid = threadIdx.x;

    int64_t inst_idx = token_instance_indices[row_idx];
    int token_idx = (int)(inst_idx / top_k);
    float w = weights[row_idx];

    const float4* src = (const float4*)(expert_out + (int64_t)row_idx * hidden_size);
    float* dst = final_out + (int64_t)token_idx * hidden_size;

    int num_float4 = hidden_size / 4;
    for (int i = tid; i < num_float4; i += blockDim.x) {
        float4 v = src[i];
        atomicAdd(dst + i*4 + 0, v.x * w);
        atomicAdd(dst + i*4 + 1, v.y * w);
        atomicAdd(dst + i*4 + 2, v.z * w);
        atomicAdd(dst + i*4 + 3, v.w * w);
    }
}

