class ModelNew(nn.Module):
    def __init__(self, hidden_size, intermediate_size, num_experts):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts
        self.combined_weights = nn.Parameter(torch.randn(num_experts, 2 * intermediate_size, hidden_size) * 0.02)
        self.down_proj = nn.Parameter(torch.randn(num_experts, hidden_size, intermediate_size) * 0.02)

    def forward(self, x, expert_indices, expert_weights):
        batch_size, seq_len, _ = x.shape
        top_k = expert_indices.shape[-1]
        x_flat = x.view(-1, self.hidden_size)
        indices_flat = expert_indices.view(-1)
        weights_flat = expert_weights.view(-1)

        # Sort tokens by expert
        perm = indices_flat.argsort()
        sorted_indices = indices_flat[perm]
        sorted_weights = weights_flat[perm]

        # Gather all tokens for all experts in one go
        # The indices of the tokens are perm // top_k
        gathered_x = x_flat[perm // top_k]

        # Count tokens per expert
        counts = torch.bincount(sorted_indices, minlength=self.num_experts).cpu().tolist()

        final_output = torch.zeros_like(x_flat)

        start = 0
        for i in range(self.num_experts):
            count = counts[i]
            if count == 0: continue

            # Single GEMM for gate and up
            # (count, hidden) @ (hidden, 2*inter) -> (count, 2*inter)
            gate_up = torch.mm(gathered_x[start : start + count], self.combined_weights[i].t())

            # Fused SiLU and Mul
            inter_out = torch.empty(count, self.intermediate_size, device=x.device, dtype=x.dtype)
            moe_kernels.fused_silu_mul_hip(gate_up, inter_out)

            # GEMM for down
            # (count, inter) @ (inter, hidden) -> (count, hidden)
            expert_out = torch.mm(inter_out, self.down_proj[i].t())

            # Scatter back
            moe_kernels.weighted_scatter_hip(
                expert_out,
                perm[start : start + count],
                sorted_weights[start : start + count],
                final_output,
                top_k
            )
            start += count

        return final_output.view(batch_size, seq_len, self.hidden_size)

