class ModelNew(nn.Module):
    def __init__(self, hidden_size, intermediate_size, num_experts):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts
        self.gate_proj = nn.Parameter(torch.randn(num_experts, intermediate_size, hidden_size) * 0.02)
        self.up_proj = nn.Parameter(torch.randn(num_experts, intermediate_size, hidden_size) * 0.02)
        self.down_proj = nn.Parameter(torch.randn(num_experts, hidden_size, intermediate_size) * 0.02)
        self.streams = [torch.cuda.Stream() for _ in range(num_experts)]

    def forward(self, x, expert_indices, expert_weights):
        batch, seq_len, _ = x.shape
        x_flat = x.view(-1, self.hidden_size)
        final_output = torch.zeros_like(x_flat)

        # Pre-find all expert masks to avoid redundant work
        for i in range(self.num_experts):
            mask = (expert_indices == i)
            if not mask.any(): continue

            # Using the default stream for where/index_select, but could be optimized
            batch_idx, seq_idx, slot_idx = torch.where(mask)
            token_indices = batch_idx * seq_len + seq_idx
            weights = expert_weights[batch_idx, seq_idx, slot_idx]
            expert_input = x_flat[token_indices]

            with torch.cuda.stream(self.streams[i]):
                gate_out = F.linear(expert_input, self.gate_proj[i])
                up_out = F.linear(expert_input, self.up_proj[i])
                inter_out = torch.empty(expert_input.size(0), self.intermediate_size, device=x.device, dtype=x.dtype)
                moe_kernels.fused_silu_mul_hip(gate_out, up_out, inter_out)
                expert_out = F.linear(inter_out, self.down_proj[i])
                moe_kernels.weighted_scatter_hip(expert_out, token_indices, weights, final_output)

        torch.cuda.synchronize()
        return final_output.view(batch, seq_len, self.hidden_size)

