import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

moe_gated_gemm_kernels_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void reorder_tokens_kernel(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int num_token_instances
) {
    int instance_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (instance_idx < num_token_instances) {
        int64_t full_token_idx = token_indices[instance_idx];
        int token_idx = full_token_idx / 2; // Each token appears top_k=2 times. No, this is wrong.
        // The token_indices already contain the correct index into the flattened x.
    }
}
// Wait, let's reconsider the reordering.
// x: (num_tokens, hidden_size)
// expert_indices: (num_tokens, top_k)
// token_indices (after argsort): (num_tokens * top_k)
// So token_indices[i] is an index in [0, num_tokens * top_k - 1].
// The original token index is token_indices[i] / top_k.

__global__ void reorder_tokens_v2(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights_flat,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int num_tokens,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = instance_info_idx / top_k;

        // Copy x[token_idx] to reordered_x[instance_idx]
        const float* src_x = x + (int64_t)token_idx * hidden_size;
        float* dst_x = reordered_x + (int64_t)instance_idx * hidden_size;
        for (int i = 0; i < hidden_size; ++i) {
            dst_x[i] = src_x[i];
        }

        reordered_weights[instance_idx] = weights_flat[instance_info_idx];
    }
}

// Optimization: use more threads per token for reordering
__global__ void reorder_tokens_v3(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights_flat,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = instance_info_idx / top_k;

        const float* src_x = x + (int64_t)token_idx * hidden_size;
        float* dst_x = reordered_x + (int64_t)instance_idx * hidden_size;

        for (int i = tid; i < hidden_size; i += blockDim.x) {
            dst_x[i] = src_x[i];
        }

        if (tid == 0) {
            reordered_weights[instance_idx] = weights_flat[instance_info_idx];
        }
    }
}

__global__ void fused_silu_mul_kernel(
    const float* __restrict__ gate_out,
    const float* __restrict__ up_out,
    float* __restrict__ out,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float g = gate_out[idx];
        float u = up_out[idx];
        // SiLU(g) * u = (g / (1 + exp(-g))) * u
        float silu_g = g / (1.0f + expf(-g));
        out[idx] = silu_g * u;
    }
}

__global__ void weighted_scatter_kernel(
    const float* __restrict__ expert_out,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ reordered_weights,
    float* __restrict__ final_out,
    int hidden_size,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = instance_info_idx / top_k;
        float weight = reordered_weights[instance_idx];

        const float* src = expert_out + (int64_t)instance_idx * hidden_size;
        float* dst = final_out + (int64_t)token_idx * hidden_size;

        for (int i = tid; i < hidden_size; i += blockDim.x) {
            // Using atomicAdd because multiple experts can contribute to the same token.
            atomicAdd(dst + i, src[i] * weight);
        }
    }
}

void reorder_tokens_hip(
    torch::Tensor x,
    torch::Tensor token_instance_indices,
    torch::Tensor weights_flat,
    torch::Tensor reordered_x,
    torch::Tensor reordered_weights,
    int top_k
) {
    int num_token_instances = token_instance_indices.size(0);
    int hidden_size = x.size(1);

    const int threads = 256;
    const int blocks = num_token_instances;

    reorder_tokens_v3<<<blocks, threads>>>(
        x.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        weights_flat.data_ptr<float>(),
        reordered_x.data_ptr<float>(),
        reordered_weights.data_ptr<float>(),
        hidden_size,
        top_k,
        num_token_instances
    );
}

void fused_silu_mul_hip(
    torch::Tensor gate_out,
    torch::Tensor up_out,
    torch::Tensor out
) {
    int size = gate_out.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    fused_silu_mul_kernel<<<blocks, threads>>>(
        gate_out.data_ptr<float>(),
        up_out.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );
}

void weighted_scatter_hip(
    torch::Tensor expert_out,
    torch::Tensor token_instance_indices,
    torch::Tensor reordered_weights,
    torch::Tensor final_out,
    int top_k
) {
    int num_token_instances = token_instance_indices.size(0);
    int hidden_size = final_out.size(1);

    const int threads = 256;
    const int blocks = num_token_instances;

    weighted_scatter_kernel<<<blocks, threads>>>(
        expert_out.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        reordered_weights.data_ptr<float>(),
        final_out.data_ptr<float>(),
        hidden_size,
        top_k,
        num_token_instances
    );
}
"""

moe_kernels = load_inline(
    name="moe_kernels",
    cpp_sources=moe_gated_gemm_kernels_code,
    functions=[
        "reorder_tokens_hip",
        "fused_silu_mul_hip",
        "weighted_scatter_hip",
    ],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, hidden_size, intermediate_size, num_experts):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

    def forward(self, x, expert_indices, expert_weights):
        batch_size, seq_len, hidden_size = x.shape
        top_k = expert_indices.shape[-1]
        num_tokens = batch_size * seq_len
        num_token_instances = num_tokens * top_k

        x_flat = x.view(num_tokens, hidden_size)
        expert_indices_flat = expert_indices.view(-1)
        expert_weights_flat = expert_weights.view(-1)

        # 1. Sort token-expert instances by expert_idx
        token_instance_indices = expert_indices_flat.argsort()
        sorted_expert_indices = expert_indices_flat[token_instance_indices]

        # 2. Reorder tokens and weights
        reordered_x = torch.empty(num_token_instances, hidden_size, device=x.device, dtype=x.dtype)
        reordered_weights = torch.empty(num_token_instances, device=x.device, dtype=x.dtype)

        moe_kernels.reorder_tokens_hip(
            x_flat,
            token_instance_indices,
            expert_weights_flat,
            reordered_x,
            reordered_weights,
            top_k
        )

        # 3. Find expert offsets
        expert_counts = torch.bincount(sorted_expert_indices, minlength=self.num_experts)
        expert_offsets = torch.cumsum(expert_counts, dim=0) - expert_counts

        # 4. Prepare output tensor
        final_output = torch.zeros(num_tokens, hidden_size, device=x.device, dtype=x.dtype)

        # 5. Loop through experts
        # We can optimize this by concatenating gate and up weights
        for i in range(self.num_experts):
            count = expert_counts[i].item()
            if count == 0:
                continue

            offset = expert_offsets[i].item()
            expert_tokens = reordered_x[offset : offset + count]

            # Gated GEMM
            # Expert gate_proj: (intermediate_size, hidden_size)
            # Expert up_proj: (intermediate_size, hidden_size)
            # Expert down_proj: (hidden_size, intermediate_size)

            gate_out = F.linear(expert_tokens, self.gate_proj[i])
            up_out = F.linear(expert_tokens, self.up_proj[i])

            # Fused SiLU and Mul
            intermediate = torch.empty(count, self.intermediate_size, device=x.device, dtype=x.dtype)
            moe_kernels.fused_silu_mul_hip(gate_out, up_out, intermediate)

            expert_out = F.linear(intermediate, self.down_proj[i])

            # Weighted Scatter
            # Instead of a full scatter kernel inside the loop, we can just do:
            # But we need to keep track of the original token indices for the scatter.
            # Let's use the weighted_scatter_hip but only for the current expert.

            # To use weighted_scatter_hip inside the loop, we need to pass the slice of token_instance_indices
            moe_kernels.weighted_scatter_hip(
                expert_out,
                token_instance_indices[offset : offset + count],
                reordered_weights[offset : offset + count],
                final_output,
                top_k
            )

        return final_output.view(batch_size, seq_len, hidden_size)

