from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

moe_gated_gemm_kernels_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void gather_to_padded_kernel(
    const float* __restrict__ x,
    const int64_t* __restrict__ expert_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ padded_x,
    float* __restrict__ padded_weights,
    int* __restrict__ expert_counts,
    int num_tokens,
    int hidden_size,
    int num_experts,
    int top_k,
    int max_count
) {
    int token_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (token_idx < num_tokens) {
        for (int k = 0; k < top_k; ++k) {
            int expert_idx = (int)expert_indices[token_idx * top_k + k];
            float weight = expert_weights[token_idx * top_k + k];

            // This is slow due to atomicAdd, but it's only once per token-expert pair.
            int pos = atomicAdd(&expert_counts[expert_idx], 1);

            if (pos < max_count) {
                const float4* src = (const float4*)(x + (int64_t)token_idx * hidden_size);
                float4* dst = (float4*)(padded_x + (int64_t)expert_idx * max_count * hidden_size + (int64_t)pos * hidden_size);

                int num_float4 = hidden_size / 4;
                for (int i = tid; i < num_float4; i += blockDim.x) {
                    dst[i] = src[i];
                }

                if (tid == 0) {
                    padded_weights[expert_idx * max_count + pos] = weight;
                    // Store original token index for scattering back
                    // We'll use a separate buffer for this.
                }
            }
        }
    }
}

// Re-thinking: To avoid atomicAdd in gather, we can pre-calculate the positions.
// But we already do that with bincount and cumsum.
// Let's use the positions from bincount and cumsum.

__global__ void gather_v4(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights_flat,
    float* __restrict__ padded_x,
    float* __restrict__ padded_weights,
    int hidden_size,
    int top_k,
    int num_experts,
    int max_count,
    const int* __restrict__ expert_offsets,
    const int* __restrict__ expert_counts,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = (int)(instance_info_idx / top_k);

        // Find which expert this instance belongs to
        // We know they are sorted, so we can find the expert_idx and its offset.
        // But it's easier to just pass the expert_idx if we have it.
        // Let's assume we know the expert_idx and the offset within that expert.
    }
}

// Actually, let's keep it simple and just use the most efficient version of what we had.
// The real bottleneck is the GEMMs. Let's try to use torch.mm but minimize everything else.

__global__ void fused_silu_mul_v4(
    const float* __restrict__ gate_up,
    float* __restrict__ out,
    int total_rows,
    int intermediate_size
) {
    int row_idx = blockIdx.x;
    int tid = threadIdx.x;

    const float4* g_ptr = (const float4*)(gate_up + (int64_t)row_idx * 2 * intermediate_size);
    const float4* u_ptr = (const float4*)(gate_up + (int64_t)row_idx * 2 * intermediate_size + intermediate_size);
    float4* d_ptr = (float4*)(out + (int64_t)row_idx * intermediate_size);

    int num_float4 = intermediate_size / 4;
    for (int i = tid; i < num_float4; i += blockDim.x) {
        float4 g = g_ptr[i];
        float4 u = u_ptr[i];
        float4 res;
        res.x = (g.x / (1.0f + expf(-g.x))) * u.x;
        res.y = (g.y / (1.0f + expf(-g.y))) * u.y;
        res.z = (g.z / (1.0f + expf(-g.z))) * u.z;
        res.w = (g.w / (1.0f + expf(-g.w))) * u.w;
        d_ptr[i] = res;
    }
}

__global__ void weighted_scatter_v4(
    const float* __restrict__ expert_out,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights,
    float* __restrict__ final_out,
    int hidden_size,
    int top_k,
    int num_rows
) {
    int row_idx = blockIdx.x;
    int tid = threadIdx.x;

    int64_t inst_idx = token_instance_indices[row_idx];
    int token_idx = (int)(inst_idx / top_k);
    float w = weights[row_idx];

    const float4* src = (const float4*)(expert_out + (int64_t)row_idx * hidden_size);
    float* dst = final_out + (int64_t)token_idx * hidden_size;

    int num_float4 = hidden_size / 4;
    for (int i = tid; i < num_float4; i += blockDim.x) {
        float4 v = src[i];
        atomicAdd(dst + i*4 + 0, v.x * w);
        atomicAdd(dst + i*4 + 1, v.y * w);
        atomicAdd(dst + i*4 + 2, v.z * w);
        atomicAdd(dst + i*4 + 3, v.w * w);
    }
}

void fused_silu_mul_hip(torch::Tensor gate_up, torch::Tensor out) {
    fused_silu_mul_v4<<<gate_up.size(0), 256>>>(gate_up.data_ptr<float>(), out.data_ptr<float>(), gate_up.size(0), out.size(1));
